changeSet.sql:
CREATE TABLE document_chunks (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    document_id  UUID NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
    equipment_id UUID REFERENCES equipment(id) ON DELETE SET NULL,  -- copied from the document, for filtering
    chunk_index  INT  NOT NULL,
    page         INT,                                               -- 1-based PDF page, NULL for text files
    content      TEXT NOT NULL,
    codes        TEXT[] NOT NULL DEFAULT '{}',
    embedding    vector(384) NOT NULL,
    content_tsv  tsvector GENERATED ALWAYS AS (to_tsvector('english', content)) STORED,
    CONSTRAINT document_chunks_unique_position UNIQUE (document_id, chunk_index)
);
CREATE INDEX idx_chunks_embedding_hnsw ON document_chunks USING hnsw (embedding vector_cosine_ops);
CREATE INDEX idx_chunks_content_tsv ON document_chunks USING gin (content_tsv);
CREATE INDEX idx_chunks_codes ON document_chunks USING gin (codes);
CREATE INDEX idx_chunks_equipment_id ON document_chunks (equipment_id);
